	private static Value[] input(Workload workload, int size) {
		Value[] values = new Value[size];
		for (int index = 0; index < size; index++) {
			values[index] = workload.value(index);
		}
		return values;
	}

	private static byte[] rdfInput(Workload workload, int size) {
		StringBuilder input = new StringBuilder();
		for (int index = 0; index < size; index++) {
			input.append("<urn:canonical-bench:subject:")
					.append(index)
					.append("> <urn:canonical-bench:predicate> <")
					.append(workload.value(index).stringValue())
					.append("> .\n");
		}
		return input.toString().getBytes(StandardCharsets.UTF_8);
	}

	private static NativeSize inspect(Path directory) throws Exception {
		long env = 0;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			env = handle.get(0);
			E(mdb_env_set_maxdbs(env, 32));
			E(mdb_env_open(env, directory.toString(), MDB_NOTLS | MDB_RDONLY, 0664));
			long[] counts = LmdbUtil.readTransaction(env, (inner, txn) -> {
				var database = inner.mallocInt(1);
				E(mdb_dbi_open(txn, (String) null, 0, database));
				PointerBuffer cursorHandle = inner.mallocPointer(1);
				E(mdb_cursor_open(txn, database.get(0), cursorHandle));
				long cursor = cursorHandle.get(0);
				long records = 0;
				long namespaces = 0;
				try {
					MDBVal key = MDBVal.calloc(inner).mv_data(inner.bytes(ValueStoreRecordCodec.ID_KEY));
					MDBVal value = MDBVal.calloc(inner);
					int rc = mdb_cursor_get(cursor, key, value, MDB_SET_RANGE);
					while (rc == MDB_SUCCESS && key.mv_data().get(0) == ValueStoreRecordCodec.ID_KEY) {
						records++;
						ByteBuffer data = value.mv_data();
						if (data.get(data.position()) == ValueStoreRecordCodec.NAMESPACE_VALUE) {
							namespaces++;
						}
						rc = mdb_cursor_get(cursor, key, value, MDB_NEXT);
					}
					if (rc != MDB_SUCCESS && rc != MDB_NOTFOUND) {
						E(rc);
					}
					return new long[] { records, namespaces };
				} finally {
					mdb_cursor_close(cursor);
				}
			});
			return new NativeSize(Files.size(directory.resolve("data.mdb")), counts[0], counts[1]);
		} finally {
			if (env != 0) {
				mdb_env_close(env);
			}
		}
	}

	private static ThreadMXBean allocations() {
		if (ManagementFactory.getThreadMXBean() instanceof ThreadMXBean bean
				&& bean.isThreadAllocatedMemorySupported()) {
			if (!bean.isThreadAllocatedMemoryEnabled()) {
				bean.setThreadAllocatedMemoryEnabled(true);
			}
			return bean;
		}
		return null;
	}

	private static long allocatedBytes() {
		return ALLOCATIONS == null ? -1L : ALLOCATIONS.getThreadAllocatedBytes(Thread.currentThread().threadId());
	}

	private static long allocationDelta(long before) {
		return before < 0 ? -1L : allocatedBytes() - before;
	}

	private static void delete(Path directory) throws IOException {
		try (var files = Files.walk(directory)) {
			for (Path path : files.sorted(Comparator.reverseOrder()).toList()) {
				Files.delete(path);
			}
		}
	}

